1	//! roottrace 库入口：为其他 Rust 程序提供 RFC 6962 成员证明（包含证明）核验。
2	//!
3	//! 命令行程序 `roottrace` 的 `root`/`prove`/`verify` 子命令同样建立在本文件的
4	//! 实现之上，因此库与命令行对同一批数据的核验结果完全一致。
5	//!
6	//! # 用法概览
7	//!
8	//! 调用方需要准备三样东西，全部在内存中，无需完整批次或临时文件：
9	//!
10	//! 1. **记录**：目标记录的全部原始字节（`&[u8]`）。每个字节都属于内容——
11	//!    空切片表示一条空记录；末尾的 LF、CR、空格、NUL 与非 UTF-8 字节都参与
12	//!    核验，不沿用批次文件的 LF 分行规则。
13	//! 2. **证明**：`roottrace prove` 输出的 JSON 证明的原始字节。字段重排、
14	//!    合法 JSON 空白与等价字符串转义按既有规则接受；重复字段、不合法的整数
15	//!    或哈希仍被拒绝。
16	//! 3. **独立确认的可信值**：树大小（`u64`，必须为正）与根值（`[u8; 32]`），
17	//!    必须来自可信渠道（签名公告、带外账本、对完整批次自行运行
18	//!    `roottrace root` 等），绝不能取自证明内部。
19	//!
20	//! 核验成功返回 [`Membership`]，可直接读取记录序号、所绑定的树大小和根值；
21	//! 返回的大小和根值就是调用方提供的可信值（已与证明核对一致），不是从证明
22	//! 里读出的字段。失败按类型区分为 [`VerifyError`] 的三个变体，库本身不向
23	//! 标准输出或标准错误打印任何内容，展示方式由调用方决定。
24	//!
25	//! 如果只想查看证明自身声明的大小、序号和根值，而没有目标记录与独立可信
26	//! 值，请改用 [`inspect_proof`]：它做同样的完整格式解读，但不做成员核验，
27	//! 其结果 [`ProofClaims`] 中的大小与根值直接来自证明、不可当作可信输入。
28	//!
29	//! # 示例
30	//!
31	//! ```
32	//! use roottrace::{verify_membership, VerifyError};
33	//!
34	//! // 只含一条空记录的批次：根值为 SHA-256(0x00)，审计路径为空。
35	//! let record: &[u8] = b"";
36	//! let proof = br#"{"tree_size":1,"leaf_index":0,"root":"6e340b9cffb37a989ca544e6bb780a2c78901d3fb33738768511a30617afa01d","audit_path":[]}"#;
37	//! let trusted_root: [u8; 32] = [
38	//!     0x6e, 0x34, 0x0b, 0x9c, 0xff, 0xb3, 0x7a, 0x98,
39	//!     0x9c, 0xa5, 0x44, 0xe6, 0xbb, 0x78, 0x0a, 0x2c,
40	//!     0x78, 0x90, 0x1d, 0x3f, 0xb3, 0x37, 0x38, 0x76,
41	//!     0x85, 0x11, 0xa3, 0x06, 0x17, 0xaf, 0xa0, 0x1d,
42	//! ];
43	//!
44	//! match verify_membership(record, proof, 1, &trusted_root) {
45	//!     Ok(m) => {
46	//!         assert_eq!(m.leaf_index(), 0);
47	//!         assert_eq!(m.tree_size(), 1);
48	//!         assert_eq!(m.root(), &trusted_root);
49	//!     }
50	//!     Err(VerifyError::MalformedProof(reason)) => {
51	//!         panic!("证明格式无效: {reason}");
52	//!     }
53	//!     Err(VerifyError::VerificationFailed(reason)) => {
54	//!         panic!("核验失败: {reason}");
55	//!     }
56	//!     Err(VerifyError::InvalidTrustedSize) => {
57	//!         panic!("可信树大小必须为正整数");
58	//!     }
59	//! }
60	//! ```
61	
62	use std::fmt;
63	
64	/// 核验成功后的类型化结果：记录在某个 Merkle 树中的成员身份已被确认。
65	///
66	/// 序号从 0 开始，指向证明声明的位置；相同内容出现在其他位置不能替代这个
67	/// 位置。树大小和根值已经与调用方的可信值核对一致——它们就是核验所锚定的
68	/// 值，而不是从证明中读出的字段。
69	#[derive(Debug, Clone, PartialEq, Eq)]
70	pub struct Membership {
71	    leaf_index: u64,
72	    tree_size: u64,
73	    root: [u8; 32],
74	}
75	
76	impl Membership {
77	    /// 被核验记录在树中的序号（从 0 开始），即证明声明的 `leaf_index`。
78	    /// 即使树大小超过平台的索引宽度，也保留完整的 64 位含义。
79	    pub fn leaf_index(&self) -> u64 {
80	        self.leaf_index
81	    }
82	
83	    /// 核验所绑定的树大小，等于调用方提供的可信树大小。
84	    pub fn tree_size(&self) -> u64 {
85	        self.tree_size
86	    }
87	
88	    /// 核验所绑定的树根值，等于调用方提供的可信根值。
89	    pub fn root(&self) -> &[u8; 32] {
90	        &self.root
91	    }
92	}
93	
94	/// 核验失败的分类，调用方可按变体区分处理方式。
95	#[derive(Debug, Clone, PartialEq, Eq)]
96	pub enum VerifyError {
97	    /// 调用参数无效：可信树大小为 0。不存在包含记录的零节点树，因此这不
98	    /// 能被当作"空树中的成员证明"接受。该判断在解读证明之前完成。
99	    InvalidTrustedSize,
100	    /// 证明格式无效：证明字节不能按现有格式解读（不是完整 JSON 对象、字段
101	    /// 缺失/重复/类型错误、整数或哈希不合法、`tree_size` 为 0、序号越界、
102	    /// 对象后有多余字节等）。附带人类可读的原因说明。
103	    MalformedProof(String),
104	    /// 核验失败：证明格式合法，但记录内容、可信树大小、可信根值或审计路径
105	    /// 不匹配。附带人类可读的原因说明。
106	    VerificationFailed(String),
107	}
108	
109	impl fmt::Display for VerifyError {
110	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
111	        match self {
112	            VerifyError::InvalidTrustedSize => {
113	                write!(f, "trusted tree size must be positive: zero cannot name a tree that holds a record")
114	            }
115	            VerifyError::MalformedProof(reason) => write!(f, "invalid proof: {reason}"),
116	            VerifyError::VerificationFailed(reason) => write!(f, "verification failed: {reason}"),
117	        }
118	    }
119	}
120	
121	impl std::error::Error for VerifyError {}
122	
123	/// 核验一条记录的 RFC 6962 成员证明，无需完整批次或临时文件。
124	///
125	/// - `record`：目标记录的全部原始字节。空切片表示一条空记录；末尾 LF、CR、
126	///   空格、NUL 与非 UTF-8 字节都属于内容，不做任何切分或修剪。
127	/// - `proof`：证明 JSON 的原始字节（如 `roottrace prove` 的输出）。字段
128	///   重排、合法空白与等价字符串转义被接受；重复字段、不合法的整数或哈希
129	///   被拒绝。
130	/// - `trusted_tree_size`：调用方**独立确认**的树大小，必须为正；为 0 时
131	///   返回 [`VerifyError::InvalidTrustedSize`]，而不是按空树核验。
132	/// - `trusted_root`：调用方**独立确认**的 32 字节根值。
133	///
134	/// 证明自带的 `tree_size` 与 `root` 只用于和可信值比对，绝不作为信任依据。
135	/// 成功时返回 [`Membership`]；失败时按 [`VerifyError`] 变体区分格式错误与
136	/// 核验失败，且不会返回任何表示已核验成功的结果。
137	pub fn verify_membership(
138	    record: &[u8],
139	    proof: &[u8],
140	    trusted_tree_size: u64,
141	    trusted_root: &[u8; 32],
142	) -> Result<Membership, VerifyError> {
143	    // 可信树大小为零是调用参数无效：必须先于证明解读拒绝，否则一份
144	    // tree_size 为 0 的"证明"会被当成空树成员证明的格式问题来报告。
145	    if trusted_tree_size == 0 {
146	        return Err(VerifyError::InvalidTrustedSize);
147	    }
148	    let proof = parse_proof(proof).map_err(VerifyError::MalformedProof)?;
149	    verify_proof(&proof, record, trusted_tree_size, trusted_root)
150	        .map_err(VerifyError::VerificationFailed)?;
151	    Ok(Membership {
152	        leaf_index: proof.leaf_index,
153	        tree_size: trusted_tree_size,
154	        root: *trusted_root,
155	    })
156	}
157	
158	/// 解读一份成员证明后、**未经任何核验**的声明值：`inspect` 操作的结果。
159	///
160	/// 与 [`Membership`] 不同，这里的树大小和根值直接来自证明自身的字段，没有
161	/// 与任何独立可信值比对，也没有目标记录可供重算路径。它们只表示“证明声称
162	/// 如此”，绝不表示记录已被证明属于该批次——即使审计路径的哈希数量、顺序或
163	/// 内容根本无法把任何记录结合到该根值，只要证明格式合法，这些字段仍会被
164	/// 原样读出。调用方不得把这里的 `tree_size()`/`root()` 当作
165	/// [`verify_membership`] 的可信输入。
166	#[derive(Debug, Clone, PartialEq, Eq)]
167	pub struct ProofClaims {
168	    tree_size: u64,
169	    leaf_index: u64,
170	    root: [u8; 32],
171	}
172	
173	impl ProofClaims {
174	    /// 证明声明的树大小（证明中的 `tree_size` 字段），保持完整 64 位无符号
175	    /// 整数含义。该值未经验证，不是独立确认的可信树大小。
176	    pub fn tree_size(&self) -> u64 {
177	        self.tree_size
178	    }
179	
180	    /// 证明声明的记录序号（证明中的 `leaf_index` 字段），从 0 开始。格式
181	    /// 合法时必有 `0 <= leaf_index < tree_size`，但该位置上是否确有该记录
182	    /// 并未核验。
183	    pub fn leaf_index(&self) -> u64 {
184	        self.leaf_index
185	    }
186	
187	    /// 证明声明的根值（证明中的 `root` 字段）。该值直接取自证明，未经
188	    /// 独立确认，不是可信根值。
189	    pub fn root(&self) -> &[u8; 32] {
190	        &self.root
191	    }
192	}
193	
194	/// 解读证明失败：证明字节不符合当前的完整证明格式。
195	#[derive(Debug, Clone, PartialEq, Eq)]
196	pub enum InspectError {
197	    /// 证明格式无效，判定标准与核验路径完全相同——不是完整 JSON 对象、
198	    /// 必需字段（含不展示的 `audit_path`）缺失/重复/类型错误、整数或哈希
199	    /// 不合法、`tree_size` 为 0、序号越界、对象后有多余字节等。附带人类
200	    /// 可读的原因说明。
201	    MalformedProof(String),
202	}
203	
204	impl fmt::Display for InspectError {
205	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
206	        match self {
207	            InspectError::MalformedProof(reason) => write!(f, "invalid proof: {reason}"),
208	        }
209	    }
210	}
211	
212	impl std::error::Error for InspectError {}
213	
214	/// 解读一份成员证明，取出它声明的树大小、记录序号与根值，**不做成员核验**。
215	///
216	/// 解读使用与 [`verify_membership`] 完全相同的完整格式判定：证明必须是一个
217	/// 完整的 JSON 对象，四个必需字段齐全且无重复，类型、整数与哈希合法，
218	/// `tree_size` 为正且 `leaf_index` 在声明范围内——即使损坏发生在不展示的
219	/// `audit_path` 中（哈希长度不对、数组未结束等）也按格式无效拒绝。字段重排、
220	/// 合法 JSON 空白与等价 Unicode 转义不影响解读结果。
221	///
222	/// 成功只代表证明符合当前格式：没有目标记录、没有独立可信值，因此既不检查
223	/// 审计路径能否证明声明的位置，也不返回任何表示核验成功的结论。需要确认
224	/// 成员身份时请改用 [`verify_membership`]。
225	pub fn inspect_proof(proof: &[u8]) -> Result<ProofClaims, InspectError> {
226	    let proof = parse_proof(proof).map_err(InspectError::MalformedProof)?;
227	    Ok(ProofClaims {
228	        tree_size: proof.tree_size,
229	        leaf_index: proof.leaf_index,
230	        root: proof.root,
231	    })
232	}
233	
234	// --- 供命令行程序复用的内部实现 ------------------------------------------------
235	//
236	// 以下项是 `roottrace` 命令行程序（src/main.rs）与库共享的实现细节，不属于
237	// 稳定的库 API，故对文档隐藏。命令行的 root/prove/verify/inspect 子命令与库
238	// 函数走完全相同的代码路径，保证两边结果一致。
239	
240	#[doc(hidden)]
241	pub fn is_lower_hex(b: u8) -> bool {
242	    b.is_ascii_digit() || (b'a'..=b'f').contains(&b)
243	}
244	
245	#[doc(hidden)]
246	pub fn hex_nibble(b: u8) -> Option<u8> {
247	    match b {
248	        b'0'..=b'9' => Some(b - b'0'),
249	        b'a'..=b'f' => Some(b - b'a' + 10),
250	        _ => None,
251	    }
252	}
253	
254	// --- Proof parsing -----------------------------------------------------------
255	//
256	// The proof must be ONE complete JSON object. `prove` output is plain JSON,
257	// but the file may also arrive over a channel that reorders fields or changes
258	// whitespace, so both are accepted. Nothing else is: a truncated value, a
259	// duplicate key, a value of the wrong JSON type, a number that is not an
260	// exact unsigned 64-bit integer, a non-lowercase/non-64-char hash, trailing
261	// bytes after the object, or an empty file all make the proof invalid.
262	// Parsing is structural: no text decoding of the proof is required for the
263	// hashes, and integer fields are accumulated digit by digit so a value above
264	// u64::MAX (including 1e400) is rejected rather than wrapped or approximated.
265	
266	/// The fields of a well-formed inclusion proof.
267	struct Proof {
268	    tree_size: u64,
269	    leaf_index: u64,
270	    root: [u8; 32],
271	    audit_path: Vec<[u8; 32]>,
272	}
273	
274	struct ProofParser<'a> {
275	    bytes: &'a [u8],
276	    pos: usize,
277	}
278	
279	fn parse_proof(input: &[u8]) -> Result<Proof, String> {
280	    let mut p = ProofParser { bytes: input, pos: 0 };
281	    p.ws();
282	    let proof = p.parse_object().map_err(|e| e.to_string())?;
283	    p.ws();
284	    if p.pos != p.bytes.len() {
285	        return Err("trailing data after the JSON object".to_string());
286	    }
287	    let tree_size = proof.tree_size.ok_or_else(|| "missing field 'tree_size'".to_string())?;
288	    let leaf_index = proof.leaf_index.ok_or_else(|| "missing field 'leaf_index'".to_string())?;
289	    let root = proof.root.ok_or_else(|| "missing field 'root'".to_string())?;
290	    let audit_path =
291	        proof.audit_path.ok_or_else(|| "missing field 'audit_path'".to_string())?;
292	    if tree_size == 0 {
293	        return Err("tree_size must be positive".to_string());
294	    }
295	    if leaf_index >= tree_size {
296	        return Err(format!(
297	            "leaf_index {leaf_index} is out of range for tree_size {tree_size}"
298	        ));
299	    }
300	    Ok(Proof { tree_size, leaf_index, root, audit_path })
301	}
302	
303	/// Accumulator for the four recognised object members; a `Some` already
304	/// present when the same key is seen again makes the proof invalid.
305	struct ProofFields {
306	    tree_size: Option<u64>,
307	    leaf_index: Option<u64>,
308	    root: Option<[u8; 32]>,
309	    audit_path: Option<Vec<[u8; 32]>>,
310	}
311	
312	impl<'a> ProofParser<'a> {
313	    fn ws(&mut self) {
314	        while self.pos < self.bytes.len() && matches!(self.bytes[self.pos], b' ' | b'\t' | b'\n' | b'\r') {
315	            self.pos += 1;
316	        }
317	    }
318	
319	    fn peek(&self) -> Option<u8> {
320	        self.bytes.get(self.pos).copied()
321	    }
322	
323	    fn eat(&mut self, b: u8) -> Result<(), String> {
324	        if self.peek() == Some(b) {
325	            self.pos += 1;
326	            Ok(())
327	        } else {
328	            Err(format!("expected '{}' at byte {}", b as char, self.pos))
329	        }
330	    }
331	
332	    fn parse_object(&mut self) -> Result<ProofFields, String> {
333	        self.eat(b'{')?;
334	        let mut fields = ProofFields {
335	            tree_size: None,
336	            leaf_index: None,
337	            root: None,
338	            audit_path: None,
339	        };
340	        self.ws();
341	        if self.peek() == Some(b'}') {
342	            self.pos += 1;
343	            return Err("empty object: none of the required fields are present".to_string());
344	        }
345	        loop {
346	            self.ws();
347	            let key = self.parse_string()?;
348	            self.ws();
349	            self.eat(b':')?;
350	            self.ws();
351	            match key.as_str() {
352	                "tree_size" => {
353	                    if fields.tree_size.is_some() {
354	                        return Err("duplicate field 'tree_size'".to_string());
355	                    }
356	                    fields.tree_size = Some(self.parse_u64()?);
357	                }
358	                "leaf_index" => {
359	                    if fields.leaf_index.is_some() {
360	                        return Err("duplicate field 'leaf_index'".to_string());
361	                    }
362	                    fields.leaf_index = Some(self.parse_u64()?);
363	                }
364	                "root" => {
365	                    if fields.root.is_some() {
366	                        return Err("duplicate field 'root'".to_string());
367	                    }
368	                    fields.root = Some(self.parse_hash()?);
369	                }
370	                "audit_path" => {
371	                    if fields.audit_path.is_some() {
372	                        return Err("duplicate field 'audit_path'".to_string());
373	                    }
374	                    fields.audit_path = Some(self.parse_hash_array()?);
375	                }
376	                other => return Err(format!("unexpected field '{other}'")),
377	            }
378	            self.ws();
379	            match self.peek() {
380	                Some(b',') => {
381	                    self.pos += 1;
382	                }
383	                Some(b'}') => {
384	                    self.pos += 1;
385	                    break;
386	                }
387	                _ => return Err(format!("expected ',' or '}}' at byte {}", self.pos)),
388	            }
389	        }
390	        Ok(fields)
391	    }
392	
393	    /// A JSON string returned as UTF-8 text. Proof keys are ASCII; escapes
394	    /// (including `\uXXXX`) are decoded so a spelled-out key cannot bypass the
395	    /// recognized-name matching. Any string value anywhere is gated through
396	    /// here, so invalid escapes or an unclosed string reject the proof.
397	    fn parse_string(&mut self) -> Result<String, String> {
398	        self.eat(b'"')?;
399	        let mut out = String::new();
400	        loop {
401	            match self.peek() {
402	                None => return Err("unterminated string".to_string()),
403	                Some(b'"') => {
404	                    self.pos += 1;
405	                    break;
406	                }
407	                Some(b'\\') => {
408	                    self.pos += 1;
409	                    match self.peek() {
410	                        Some(b'"') => out.push('"'),
411	                        Some(b'\\') => out.push('\\'),
412	                        Some(b'/') => out.push('/'),
413	                        Some(b'b') => out.push('\u{0008}'),
414	                        Some(b'f') => out.push('\u{000C}'),
415	                        Some(b'n') => out.push('\n'),
416	                        Some(b'r') => out.push('\r'),
417	                        Some(b't') => out.push('\t'),
418	                        Some(b'u') => {
419	                            self.pos += 1;
420	                            let cp = self.parse_hex4()?;
421	                            // High surrogate demands a matching low surrogate.
422	                            let cp = if (0xD800..=0xDBFF).contains(&cp) {
423	                                if self.peek() != Some(b'\\') {
424	                                    return Err("lone high surrogate".to_string());
425	                                }
426	                                self.pos += 1;
427	                                if self.peek() != Some(b'u') {
428	                                    return Err("lone high surrogate".to_string());
429	                                }
430	                                self.pos += 1;
431	                                let lo = self.parse_hex4()?;
432	                                if !(0xDC00..=0xDFFF).contains(&lo) {
433	                                    return Err("high surrogate not followed by a low surrogate".to_string());
434	                                }
435	                                0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00)
436	                            } else if (0xDC00..=0xDFFF).contains(&cp) {
437	                                return Err("lone low surrogate".to_string());
438	                            } else {
439	                                cp
440	                            };
441	                            match char::from_u32(cp) {
442	                                Some(c) => out.push(c),
443	                                None => return Err("invalid unicode escape".to_string()),
444	                            }
445	                            continue;
446	                        }
447	                        _ => return Err("invalid escape sequence".to_string()),
448	                    }
449	                    self.pos += 1;
450	                }
451	                Some(_) => {
452	                    // Copy a run of ordinary bytes, reinterpreting the slice as
453	                    // UTF-8 for appending; control characters and invalid UTF-8
454	                    // inside a string are rejected. The run stops at ASCII
455	                    // delimiters only, so a multibyte sequence is never split.
456	                    let start = self.pos;
457	                    while self.pos < self.bytes.len() {
458	                        let b = self.bytes[self.pos];
459	                        if b == b'"' || b == b'\\' {
460	                            break;
461	                        }
462	                        if b < 0x20 {
463	                            return Err("unescaped control character in string".to_string());
464	                        }
465	                        self.pos += 1;
466	                    }
467	                    match std::str::from_utf8(&self.bytes[start..self.pos]) {
468	                        Ok(s) => out.push_str(s),
469	                        Err(_) => return Err("string is not valid UTF-8".to_string()),
470	                    }
471	                }
472	            }
473	        }
474	        Ok(out)
475	    }
476	
477	    fn parse_hex4(&mut self) -> Result<u32, String> {
478	        if self.pos + 4 > self.bytes.len() {
479	            return Err("truncated unicode escape".to_string());
480	        }
481	        let mut v = 0u32;
482	        for _ in 0..4 {
483	            let b = self.bytes[self.pos];
484	            self.pos += 1;
485	            let n = match b {
486	                b'0'..=b'9' => u32::from(b - b'0'),
487	                b'a'..=b'f' => u32::from(b - b'a' + 10),
488	                b'A'..=b'F' => u32::from(b - b'A' + 10),
489	                _ => return Err("invalid hex digit in unicode escape".to_string()),
490	            };
491	            v = (v << 4) | n;
492	        }
493	        Ok(v)
494	    }
495	
496	    /// A JSON number accepted only when it is an exact unsigned 64-bit
497	    /// integer token: digits only, no sign, fraction or exponent.
498	    fn parse_u64(&mut self) -> Result<u64, String> {
499	        let start = self.pos;
500	        while self.peek().is_some_and(|b| b.is_ascii_digit()) {
501	            self.pos += 1;
502	        }
503	        if start == self.pos {
504	            return Err("expected an unsigned integer".to_string());
505	        }
506	        // Canonical JSON integer token: "0" alone is allowed, but no leading
507	        // zeros (so "01" is rejected, not read as 1).
508	        if self.pos - start > 1 && self.bytes[start] == b'0' {
509	            return Err("integer must not have leading zeros".to_string());
510	        }
511	        if self.peek().is_some_and(|b| matches!(b, b'.' | b'e' | b'E' | b'+' | b'-')) {
512	            return Err("number must be an unsigned 64-bit integer".to_string());
513	        }
514	        let text = std::str::from_utf8(&self.bytes[start..self.pos])
515	            .map_err(|_| "integer is not ASCII".to_string())?;
516	        let mut value: u64 = 0;
517	        for b in text.bytes() {
518	            value = value
519	                .checked_mul(10)
520	                .and_then(|v| v.checked_add(u64::from(b - b'0')))
521	                .ok_or_else(|| "integer exceeds unsigned 64-bit range".to_string())?;
522	        }
523	        Ok(value)
524	    }
525	
526	    /// A JSON string that must contain exactly 64 lowercase hexadecimal
527	    /// characters, decoded to 32 bytes.
528	    fn parse_hash(&mut self) -> Result<[u8; 32], String> {
529	        let s = self.parse_string()?;
530	        if s.len() != 64 || !s.bytes().all(is_lower_hex) {
531	            return Err("hash must be a string of 64 lowercase hexadecimal characters".to_string());
532	        }
533	        let bytes = s.as_bytes();
534	        let mut out = [0u8; 32];
535	        for (i, pair) in bytes.chunks_exact(2).enumerate() {
536	            out[i] = (hex_nibble(pair[0]).unwrap() << 4) | hex_nibble(pair[1]).unwrap();
537	        }
538	        Ok(out)
539	    }
540	
541	    fn parse_hash_array(&mut self) -> Result<Vec<[u8; 32]>, String> {
542	        self.eat(b'[')?;
543	        let mut hashes = Vec::new();
544	        self.ws();
545	        if self.peek() == Some(b']') {
546	            self.pos += 1;
547	            return Ok(hashes);
548	        }
549	        loop {
550	            self.ws();
551	            hashes.push(self.parse_hash()?);
552	            self.ws();
553	            match self.peek() {
554	                Some(b',') => {
555	                    self.pos += 1;
556	                }
557	                Some(b']') => {
558	                    self.pos += 1;
559	                    break;
560	                }
561	                _ => return Err(format!("expected ',' or ']' at byte {}", self.pos)),
562	            }
563	        }
564	        Ok(hashes)
565	    }
566	}
