655	// --- Record division --------------------------------------------------------
656	//
657	// This is the SINGLE place that maintains how a raw byte batch is divided into
658	// records. Both commands drive the same rule:
659	//
660	// - `prove` scans an already-read batch with [`RecordScanner::scan`], collecting
661	//   one slice per record ([`split_records`]);
662	// - `root` feeds its fixed-size read buffer chunk by chunk to the same
663	//   [`RecordScanner`] inside [`RootStream`], so a read boundary is never a
664	//   record boundary.
665	//
666	// The rule, byte for byte:
667	//
668	// - LF (0x0a) separates records and is never itself content. Every other byte
669	//   — CR, space, tab, NUL, a non-UTF-8 byte — is content delivered verbatim;
670	//   there is no text decoding, trimming or newline normalization.
671	// - A record comes into existence either by receiving content or by being
672	//   terminated with an LF. Leading and consecutive LFs therefore keep their
673	//   empty records; an empty input is zero records, while a single LF is one
674	//   empty record.
675	// - A trailing LF only terminates the record in progress and adds no empty
676	//   record; a final record without a trailing LF is the same record sequence.
677	//
678	// The division is expressed as an event sink ([`RecordSink`]) rather than as a
679	// returned list, so the streaming caller never has to accumulate a complete
680	// record or batch: `record_bytes` hands out sub-slices straight from the chunk
681	// being scanned.
682	
683	/// Receives the division of a byte stream into records from
684	/// [`RecordScanner`]. Every method sees raw bytes only; the scanner alone
685	/// decides *when* each event fires, so a sink never re-interprets LF or the
686	/// end of stream.
687	trait RecordSink {
688	    /// A non-empty run of content bytes belonging to the record currently in
689	    /// progress; the slice is borrowed from the chunk being scanned and must
690	    /// not be relied on after the call returns. One record arrives as any
691	    /// number of these runs (a long record spanning many chunks gets many),
692	    /// but an empty record gets none.
693	    fn record_bytes(&mut self, bytes: &[u8]);
694	
695	    /// One record was terminated by an LF (which is never delivered as
696	    /// content). Fires for every LF in the stream, including a leading LF and
697	    /// the second of two consecutive LFs — those close empty records.
698	    fn record_end(&mut self);
699	
700	    /// The stream ended right after content bytes with no terminating LF, so
701	    /// that content is itself the final record. Fires at most once, only when
702	    /// such content exists; after a bare trailing LF it does not fire.
703	    fn tail_end(&mut self);
704	}
705	
706	/// The shared record-boundary state machine. Independent of how the bytes are
707	/// obtained: one whole batch ([`RecordScanner::scan`]) or arbitrarily sized
708	/// chunks fed across reads ([`RecordScanner::feed`]) divide into exactly the
709	/// same record sequence. The only state it keeps is whether a content-only
710	/// record is open at the end of the last chunk, so nothing grows with the
711	/// number of records or their length.
712	struct RecordScanner<S: RecordSink> {
713	    sink: S,
714	    /// Content has arrived for the record currently in progress and no LF has
715	    /// closed it yet. Decides whether [`RecordSink::tail_end`] fires at end of
716	    /// stream — the one place the "trailing LF adds no record" rule lives.
717	    open: bool,
718	}
719	
720	impl<S: RecordSink> RecordScanner<S> {
721	    fn new(sink: S) -> Self {
722	        RecordScanner { sink, open: false }
723	    }
724	
725	    /// Feed the next chunk. Read boundaries fall inside content or on LF
726	    /// bytes; either way the division sees no boundary of its own — an LF split
727	    /// across two chunks still ends the record, and two LFs in adjacent chunks
728	    /// keep the empty record between them.
729	    fn feed(&mut self, chunk: &[u8]) {
730	        let mut rest = chunk;
731	        while let Some(pos) = rest.iter().position(|&b| b == b'\n') {
732	            // Content before this LF (nothing for a leading/consecutive LF);
733	            // the empty-run case must not look like content.
734	            if pos > 0 {
735	                self.sink.record_bytes(&rest[..pos]);
736	            }
737	            self.sink.record_end();
738	            rest = &rest[pos + 1..];
739	            self.open = false;
740	        }
741	        // Bytes after the last LF (or all of an LF-free chunk) open the
742	        // record the next chunk or end of stream will close.
743	        if !rest.is_empty() {
744	            self.sink.record_bytes(rest);
745	            self.open = true;
746	        }
747	    }
748	
749	    /// Finish the stream and give back the sink.
750	    fn finish(mut self) -> S {
751	        if self.open {
752	            self.sink.tail_end();
753	        }
754	        self.sink
755	    }
756	
757	    /// Convenience for callers that already hold the whole input: divide it in
758	    /// one pass.
759	    fn scan(self, data: &[u8]) -> S {
760	        let mut scanner = self;
761	        scanner.feed(data);
762	        scanner.finish()
763	    }
764	}
765	
766	/// Divide a complete batch into records on LF (0x0a), per the shared rule
767	/// documented on [`RecordScanner`]. The separator is not part of any record; a
768	/// trailing LF terminates the last record without adding an empty one; an empty
769	/// file yields zero records and a file containing one LF yields one empty
770	/// record.
771	#[doc(hidden)]
772	pub fn split_records(data: &[u8]) -> Vec<&[u8]> {
773	    /// Sink for the whole-batch case: content runs of one record are stitched
774	    /// back into slice positions. A run never crosses a chunk boundary here
775	    /// (the whole batch is one feed), but every record goes through the same
776	    /// content/end events as the streaming path.
777	    struct CollectRecords<'a> {
778	        data: &'a [u8],
779	        records: Vec<&'a [u8]>,
780	        /// Start offset of the record currently in progress. `None` until the
781	        /// record actually receives content: a record exists only once it has
782	        /// content or is terminated by an LF, so an empty input stays empty.
783	        start: Option<usize>,
784	        pos: usize,
785	    }
786	
787	    impl<'a> RecordSink for CollectRecords<'a> {
788	        fn record_bytes(&mut self, bytes: &[u8]) {
789	            // The scanner only calls this with non-empty content; the first run
790	            // of a record opens it at the byte it starts at.
791	            if self.start.is_none() {
792	                self.start = Some(self.pos);
793	            }
794	            self.pos += bytes.len();
795	        }
796	
797	        fn record_end(&mut self) {
798	            // Termination by LF always closes a record, even an empty one.
799	            let start = self.start.take().unwrap_or(self.pos);
800	            self.records.push(&self.data[start..self.pos]);
801	            self.pos += 1; // the terminating LF
802	        }
803	
804	        fn tail_end(&mut self) {
805	            // Only reached when content without a trailing LF is open.
806	            let start = self.start.take().expect("tail_end implies open content");
807	            self.records.push(&self.data[start..self.pos]);
808	        }
809	    }
810	
811	    let collector = RecordScanner::new(CollectRecords {
812	        data,
813	        records: Vec::new(),
814	        start: None,
815	        pos: 0,
816	    })
817	    .scan(data);
818	    collector.records
819	}
