821	/// A fresh leaf hasher primed with the RFC 6962 section 2.1 leaf prefix 0x00.
822	fn new_leaf_hasher() -> Sha256 {
823	    let mut h = Sha256::new();
824	    h.update(&[0x00]);
825	    h
826	}
