918	/// RFC 6962 section 2.1 Merkle Tree Hash over SHA-256: the batch root, built
919	/// by the shared `build_tree` constructor so it follows exactly the same
920	/// rules as proof generation.
921	#[doc(hidden)]
922	pub fn mth(leaves: &[&[u8]]) -> [u8; 32] {
923	    build_tree(leaves, None, &mut Vec::new())
924	}
