926	/// RFC 6962 section 2.1.1: the Merkle Tree Hash of the whole batch together
927	/// with the Merkle Audit Path for the record at `m`, both produced by the
928	/// shared `build_tree` constructor. The returned path is ordered from the
929	/// leaf level up to the root and is empty for a batch of exactly one record.
930	#[doc(hidden)]
931	pub fn root_and_path(leaves: &[&[u8]], m: usize) -> ([u8; 32], Vec<[u8; 32]>) {
932	    let n = leaves.len();
933	    assert!(m < n, "leaf index {m} out of range for {n} record(s)");
934	    let mut path = Vec::new();
935	    let root = build_tree(leaves, Some(m), &mut path);
936	    (root, path)
937	}
