1161	/// Streaming SHA-256 (FIPS 180-4). The working state is the eight hash words
1162	/// plus one 64-byte block buffer, so the temporary memory a hash needs is a
1163	/// small constant no matter how long the hashed input is: a record is fed in
1164	/// place from the batch buffer and is never copied for hashing.
1165	struct Sha256 {
1166	    h: [u32; 8],
1167	    buf: [u8; 64],
1168	    buf_len: usize,
1169	    total_len: u64,
1170	}
1171	
1172	impl Sha256 {
1173	    fn new() -> Self {
1174	        #[cfg(test)]
1175	        SHA256_CALLS.with(|c| c.set(c.get() + 1));
1176	        Sha256 {
1177	            h: [
1178	                0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c,
1179	                0x1f83d9ab, 0x5be0cd19,
1180	            ],
1181	            buf: [0u8; 64],
1182	            buf_len: 0,
1183	            total_len: 0,
1184	        }
1185	    }
1186	
1187	    /// Feed the next chunk of input. Bytes are consumed straight from `data`;
1188	    /// only a partial trailing block is ever staged in `buf`.
1189	    fn update(&mut self, mut data: &[u8]) {
1190	        self.total_len = self.total_len.wrapping_add(data.len() as u64);
1191	        if self.buf_len > 0 {
1192	            let take = (64 - self.buf_len).min(data.len());
1193	            self.buf[self.buf_len..self.buf_len + take].copy_from_slice(&data[..take]);
1194	            self.buf_len += take;
1195	            data = &data[take..];
1196	            if self.buf_len == 64 {
1197	                let block = self.buf;
1198	                self.compress(&block);
1199	                self.buf_len = 0;
1200	            }
1201	        }
1202	        while data.len() >= 64 {
1203	            let (block, rest) = data.split_at(64);
1204	            let mut staged = [0u8; 64];
1205	            staged.copy_from_slice(block);
1206	            self.compress(&staged);
1207	            data = rest;
1208	        }
1209	        if !data.is_empty() {
1210	            self.buf[..data.len()].copy_from_slice(data);
1211	            self.buf_len = data.len();
1212	        }
1213	    }
1214	
1215	    /// Append the FIPS 180-4 padding (0x80, zeros, 64-bit big-endian bit
1216	    /// length) inside the block buffer and produce the digest. At most one
1217	    /// extra block is needed when the length field does not fit after the
1218	    /// final data byte.
1219	    fn finalize(mut self) -> [u8; 32] {
1220	        let bit_len = self.total_len.wrapping_mul(8);
1221	        self.update(&[0x80]);
1222	        while self.buf_len != 56 {
1223	            self.update(&[0]);
1224	        }
1225	        self.update(&bit_len.to_be_bytes());
1226	        debug_assert_eq!(self.buf_len, 0, "padding must end on a block boundary");
1227	
1228	        let mut out = [0u8; 32];
1229	        for (i, word) in self.h.iter().enumerate() {
1230	            out[i * 4..i * 4 + 4].copy_from_slice(&word.to_be_bytes());
1231	        }
1232	        out
1233	    }
1234	
1235	    /// The SHA-256 compression function over one 64-byte block.
1236	    fn compress(&mut self, block: &[u8; 64]) {
1237	        let mut w = [0u32; 64];
1238	        for (i, word) in block.chunks_exact(4).enumerate() {
1239	            w[i] = u32::from_be_bytes([word[0], word[1], word[2], word[3]]);
1240	        }
1241	        for i in 16..64 {
1242	            let s0 = w[i - 15].rotate_right(7) ^ w[i - 15].rotate_right(18) ^ (w[i - 15] >> 3);
1243	            let s1 = w[i - 2].rotate_right(17) ^ w[i - 2].rotate_right(19) ^ (w[i - 2] >> 10);
1244	            w[i] = w[i - 16]
1245	                .wrapping_add(s0)
1246	                .wrapping_add(w[i - 7])
1247	                .wrapping_add(s1);
1248	        }
1249	
1250	        let [mut a, mut b, mut c, mut d, mut e, mut f, mut g, mut hh] = self.h;
1251	        for i in 0..64 {
1252	            let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
1253	            let ch = (e & f) ^ ((!e) & g);
1254	            let t1 = hh
1255	                .wrapping_add(s1)
1256	                .wrapping_add(ch)
1257	                .wrapping_add(K[i])
1258	                .wrapping_add(w[i]);
1259	            let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
1260	            let maj = (a & b) ^ (a & c) ^ (b & c);
1261	            let t2 = s0.wrapping_add(maj);
1262	            hh = g;
1263	            g = f;
1264	            f = e;
1265	            e = d.wrapping_add(t1);
1266	            d = c;
1267	            c = b;
1268	            b = a;
1269	            a = t1.wrapping_add(t2);
1270	        }
1271	
1272	        self.h[0] = self.h[0].wrapping_add(a);
1273	        self.h[1] = self.h[1].wrapping_add(b);
1274	        self.h[2] = self.h[2].wrapping_add(c);
1275	        self.h[3] = self.h[3].wrapping_add(d);
1276	        self.h[4] = self.h[4].wrapping_add(e);
1277	        self.h[5] = self.h[5].wrapping_add(f);
1278	        self.h[6] = self.h[6].wrapping_add(g);
1279	        self.h[7] = self.h[7].wrapping_add(hh);
1280	    }
1281	}
