261	/// Anything else (sign, whitespace, non-UTF-8 bytes, a value above u64::MAX)
262	/// is a usage error.
263	fn parse_trusted_size(arg: &OsStr) -> Option<u64> {
264	    let text = arg.to_str()?;
265	    if text.is_empty() || !text.bytes().all(|b| b.is_ascii_digit()) {
266	        return None;
267	    }
268	    let mut value: u64 = 0;
269	    for b in text.bytes() {
270	        value = value.checked_mul(10)?.checked_add(u64::from(b - b'0'))?;
271	    }
272	    if value == 0 {
273	        return None;
274	    }
275	    Some(value)
