1	//! End-to-end regression tests for verifying records that THEMSELVES contain
2	//! LF bytes, through both the `roottrace verify` command and the
3	//! `roottrace::verify_membership` library entry point.
4	//!
5	//! The record file of `verify` and the `record: &[u8]` argument of the
6	//! library are taken as raw bytes with no LF splitting and no trimming (the
7	//! LF-separated batch file is a `root`/`prove` concept). Existing coverage
8	//! pins that APPENDING an LF to a normal record fails; these tests pin the
9	//! success side: a legitimate record whose own bytes contain LF verifies as
10	//! one complete record. Such a record can never appear inside a batch file
11	//! (LF is the separator there), so the fixed proofs and trusted roots come
12	//! from `tests/reference/rfc6962_lf_record_vectors.py` — two structurally
13	//! different RFC 6962 implementations over `hashlib.sha256`, cross-checked
14	//! and re-verified by an independent inclusion verifier — and are never
15	//! derived from roottrace output.
16	//!
17	//! Coverage:
18	//!   * REC_LF_RICH: starts with LF, consecutive LFs inside, ends with LF,
19	//!     carries CR/NUL/non-UTF-8 bytes, 100 bytes long so the leaf input
20	//!     crosses the SHA-256 64-byte block boundary — verifies in a
21	//!     single-record tree (empty audit path) and in a 9-record
22	//!     non-power-of-two tree (position 4)
23	//!   * REC_ONE_LF: exactly one LF byte — verifies in both tree shapes and is
24	//!     neither the zero-byte empty record nor the batch-file empty record
25	//!   * the LFs inside the record do not change the proof's declared
26	//!     tree_size/leaf_index, and verification does not match any single
27	//!     line of the record
28	//!   * mutations (trailing LF removed, one internal LF changed) fail as
29	//!     "verification failed" — exit 1, empty stdout — never as "invalid
30	//!     proof" and never successfully; the library returns
31	//!     VerifyError::VerificationFailed
32	//!   * CLI success output is exactly "verified\n" with exit 0 and empty
33	//!     stderr; the library result carries the claimed index and the
34	//!     caller's trusted size and root
35	
36	mod common;
37	
38	use std::process::Command;
39	
40	use common::TempFile;
41	use roottrace::{verify_membership, VerifyError};
42	
43	// --- Fixed records, roots and paths (copied from the reference generator) --
44	
45	// REC_LF_RICH: 100-byte record; starts with LF, consecutive LFs inside,
46	// ends with LF, carries CR/NUL/non-UTF-8 bytes; leaf input 101 bytes
47	// crosses the SHA-256 64-byte block boundary.
48	const REC_LF_RICH: &[u8] = b"\n\x00\xff\xfe\rlf-rich-record:\n\n\nsegment-B\r\nabcdefghijklmnopqrstuvwxyz0123456789abcdefghijklmnopqrstuvwxyz012\n";
49	
50	// REC_ONE_LF: the record that is exactly one LF byte.
51	const REC_ONE_LF: &[u8] = b"\n";
52	
53	// Single-record trees (tree_size 1, leaf_index 0, empty audit path):
54	const ROOT_LF_RICH_SINGLE: &str = "173226ff98963fba71af8e5be5a65b8801b57802a8da0f3df194630a60e3c6b4";
55	const ROOT_ONE_LF_SINGLE: &str = "67ebbd370daa02ba9aadd05d8e091e862d0d8bcadafdf2a22360240a42fe922e";
56	
57	// LF_BATCH: 9-record (non-power-of-two) sequence with REC_LF_RICH at
58	// position 4 and REC_ONE_LF at position 8 (lone right subtree).
59	const ROOT_LF_BATCH: &str = "0da784b08ff8dc5d6ce28573aef2f1870116467b242aea9bdddc09e7878ea281";
60	const PATH_LF_BATCH_M4: &[&str] = &["874bb321567c2878c37d117d7b4844d505bba48fb28ef79e9a384783cd83981c", "3fc0ce0f8d78eb619bf4d612fea9ce899778ce65c0f4057ccdff93d5e5a1cb11", "24ff5ce2ca4e64d47365292c6d5408d2118f70f3eb7d4baf88caf779e61cc1c5", "67ebbd370daa02ba9aadd05d8e091e862d0d8bcadafdf2a22360240a42fe922e"];
61	const PATH_LF_BATCH_M8: &[&str] = &["6815e839c7f397a279197c64b82fa20441773460c830112ced04f25607a30d8f"];
62	
63	// The batch-file empty record's root (SHA-256(0x00)), fixed independently in
64	// tests/reference/rfc6962_vectors.py and reused by verify_regression.rs: the
65	// one-LF record must NOT verify against it.
66	const ROOT_ONE_EMPTY_RECORD: &str =
67	    "6e340b9cffb37a989ca544e6bb780a2c78901d3fb33738768511a30617afa01d";
68	
69	fn proof_json(size: u64, index: u64, root: &str, path: &[&str]) -> String {
70	    let mut out =
71	        format!("{{\"tree_size\":{size},\"leaf_index\":{index},\"root\":\"{root}\",\"audit_path\":[");
72	    for (i, h) in path.iter().enumerate() {
73	        if i > 0 {
74	            out.push(',');
75	        }
76	        out.push('"');
77	        out.push_str(h);
78	        out.push('"');
79	    }
80	    out.push_str("]}");
81	    out
82	}
83	
84	/// Decode 64 lowercase hex characters into a 32-byte hash.
85	fn hash_of(hex: &str) -> [u8; 32] {
86	    assert_eq!(hex.len(), 64, "hash must be 64 hex chars: {hex:?}");
87	    let mut out = [0u8; 32];
88	    for (i, pair) in hex.as_bytes().chunks_exact(2).enumerate() {
89	        let nibble = |b: u8| -> u8 {
90	            match b {
91	                b'0'..=b'9' => b - b'0',
92	                b'a'..=b'f' => b - b'a' + 10,
93	                _ => panic!("not lowercase hex: {hex:?}"),
94	            }
95	        };
96	        out[i] = (nibble(pair[0]) << 4) | nibble(pair[1]);
97	    }
98	    out
99	}
100	
101	fn run(
102	    record: &std::path::Path,
103	    proof: &std::path::Path,
104	    size: &str,
105	    root: &str,
106	) -> std::process::Output {
107	    Command::new(common::bin())
108	        .arg("verify")
109	        .arg(record)
110	        .arg(proof)
111	        .arg(size)
112	        .arg(root)
113	        .output()
114	        .expect("failed to execute roottrace binary")
115	}
116	
117	fn assert_verified(desc: &str, record: &[u8], proof: &[u8], size: &str, root: &str) {
118	    let rec = TempFile::create(record);
119	    let prf = TempFile::create(proof);
120	    let out = run(&rec.path, &prf.path, size, root);
121	    if out.status.code() != Some(0) || out.stdout != b"verified\n" || !out.stderr.is_empty() {
122	        panic!(
123	            "[{desc}] expected verified/exit0/empty-stderr\n\
124	             status: {:?}\nstdout: {:?}\nstderr: {}",
125	            out.status.code(),
126	            out.stdout,
127	            String::from_utf8_lossy(&out.stderr),
128	        );
129	    }
130	}
131	
132	/// The failure must be classified as a verification failure (exit 1, empty
133	/// stdout, "verification failed" on stderr) — never as a malformed proof.
134	fn assert_verification_failed(desc: &str, record: &[u8], proof: &[u8], size: &str, root: &str) {
135	    let rec = TempFile::create(record);
136	    let prf = TempFile::create(proof);
137	    let out = run(&rec.path, &prf.path, size, root);
138	    assert_eq!(out.status.code(), Some(1), "[{desc}] must exit 1");
139	    assert!(out.stdout.is_empty(), "[{desc}] stdout must be empty, got {:?}", out.stdout);
140	    let err = String::from_utf8_lossy(&out.stderr);
141	    assert!(err.contains("verification failed"), "[{desc}] stderr: {err}");
142	    assert!(!err.contains("invalid proof"), "[{desc}] must not be a format error: {err}");
143	}
144	
145	// --- Success: LF-containing records verify as one complete record ----------
146	
147	#[test]
148	fn lf_rich_record_verifies_as_one_record_in_both_tree_shapes() {
149	    // Structural requirements the whole test file relies on.
150	    assert_eq!(REC_LF_RICH.len(), 100);
151	    assert!(1 + REC_LF_RICH.len() > 64, "leaf input must cross the 64-byte block boundary");
152	    assert_eq!(REC_LF_RICH[0], b'\n', "starts with LF");
153	    assert_eq!(REC_LF_RICH[REC_LF_RICH.len() - 1], b'\n', "ends with LF");
154	    assert!(REC_LF_RICH.windows(3).any(|w| w == b"\n\n\n"), "consecutive LFs inside");
155	    assert!(REC_LF_RICH.contains(&0x00) && REC_LF_RICH.contains(&b'\r'));
156	    assert!(REC_LF_RICH.iter().any(|&b| b >= 0x80), "non-UTF-8 bytes inside");
157	
158	    // Single-record tree: empty audit path, the record is the whole tree.
159	    let single = proof_json(1, 0, ROOT_LF_RICH_SINGLE, &[]);
160	    assert_verified(
161	        "LF-rich record, single-record tree",
162	        REC_LF_RICH,
163	        single.as_bytes(),
164	        "1",
165	        ROOT_LF_RICH_SINGLE,
166	    );
167	
168	    // Non-power-of-two 9-record tree: the record sits at position 4 with the
169	    // audit path for that position. The LFs inside the record do not change
170	    // the declared tree size or position.
171	    let batch = proof_json(9, 4, ROOT_LF_BATCH, PATH_LF_BATCH_M4);
172	    assert!(
173	        batch.starts_with("{\"tree_size\":9,\"leaf_index\":4,"),
174	        "the proof declares tree_size 9 and leaf_index 4 regardless of the LFs: {batch}"
175	    );
176	    assert_verified(
177	        "LF-rich record, 9-record tree position 4",
178	        REC_LF_RICH,
179	        batch.as_bytes(),
180	        "9",
181	        ROOT_LF_BATCH,
182	    );
183	}
184	
185	#[test]
186	fn one_lf_record_verifies_and_is_not_the_empty_record() {
187	    // Exactly one LF byte: verifies in both tree shapes.
188	    let single = proof_json(1, 0, ROOT_ONE_LF_SINGLE, &[]);
189	    assert_verified(
190	        "one-LF record, single-record tree",
191	        REC_ONE_LF,
192	        single.as_bytes(),
193	        "1",
194	        ROOT_ONE_LF_SINGLE,
195	    );
196	    let batch = proof_json(9, 8, ROOT_LF_BATCH, PATH_LF_BATCH_M8);
197	    assert_verified(
198	        "one-LF record, 9-record tree position 8",
199	        REC_ONE_LF,
200	        batch.as_bytes(),
201	        "9",
202	        ROOT_LF_BATCH,
203	    );
204	
205	    // It is NOT the zero-byte empty record: the empty record's own proof
206	    // (tree_size 1, root SHA-256(0x00)) must reject the one-LF record...
207	    assert_verification_failed(
208	        "one-LF record against the empty-record proof",
209	        REC_ONE_LF,
210	        proof_json(1, 0, ROOT_ONE_EMPTY_RECORD, &[]).as_bytes(),
211	        "1",
212	        ROOT_ONE_EMPTY_RECORD,
213	    );
214	    // ...and the zero-byte record file must not verify against the one-LF
215	    // proofs, in either tree shape.
216	    assert_verification_failed(
217	        "zero-byte record file against the one-LF single proof",
218	        b"",
219	        single.as_bytes(),
220	        "1",
221	        ROOT_ONE_LF_SINGLE,
222	    );
223	    assert_verification_failed(
224	        "zero-byte record file against the one-LF batch proof",
225	        b"",
226	        batch.as_bytes(),
227	        "9",
228	        ROOT_LF_BATCH,
229	    );
230	    // Two LFs are yet another record; consecutive LFs are content, not
231	    // "two empty records".
232	    assert_verification_failed(
233	        "two-LF record file against the one-LF single proof",
234	        b"\n\n",
235	        single.as_bytes(),
236	        "1",
237	        ROOT_ONE_LF_SINGLE,
238	    );
239	}
240	
241	// --- Mutations of an LF-containing record fail verification ----------------
242	
243	#[test]
244	fn lf_rich_record_mutations_fail_verification_in_both_tree_shapes() {
245	    let single = proof_json(1, 0, ROOT_LF_RICH_SINGLE, &[]);
246	    let batch = proof_json(9, 4, ROOT_LF_BATCH, PATH_LF_BATCH_M4);
247	
248	    // Only the trailing LF removed: the record becomes a different one.
249	    let no_trailing = &REC_LF_RICH[..REC_LF_RICH.len() - 1];
250	    assert_verification_failed(
251	        "trailing LF removed, single-record tree",
252	        no_trailing,
253	        single.as_bytes(),
254	        "1",
255	        ROOT_LF_RICH_SINGLE,
256	    );
257	    assert_verification_failed(
258	        "trailing LF removed, 9-record tree",
259	        no_trailing,
260	        batch.as_bytes(),
261	        "9",
262	        ROOT_LF_BATCH,
263	    );
264	
265	    // One INTERNAL LF changed (the middle LF of the consecutive run becomes
266	    // a vertical tab), every other byte unchanged and the length preserved.
267	    assert_eq!(REC_LF_RICH[21], b'\n', "byte 21 is an internal LF");
268	    let mut internal_changed = REC_LF_RICH.to_vec();
269	    internal_changed[21] = 0x0b;
270	    assert_verification_failed(
271	        "one internal LF changed, single-record tree",
272	        &internal_changed,
273	        single.as_bytes(),
274	        "1",
275	        ROOT_LF_RICH_SINGLE,
276	    );
277	    assert_verification_failed(
278	        "one internal LF changed, 9-record tree",
279	        &internal_changed,
280	        batch.as_bytes(),
281	        "9",
282	        ROOT_LF_BATCH,
283	    );
284	
285	    // Verification must not fall back to matching a single LINE of the
286	    // record: no LF-delimited segment of it is the record.
287	    for line in [
288	        b"\x00\xff\xfe\rlf-rich-record:".as_slice(),
289	        b"segment-B\r".as_slice(),
290	        b"abcdefghijklmnopqrstuvwxyz0123456789abcdefghijklmnopqrstuvwxyz012".as_slice(),
291	        b"".as_slice(),
292	    ] {
293	        assert_verification_failed(
294	            &format!("a single line of the record {line:?}"),
295	            line,
296	            batch.as_bytes(),
297	            "9",
298	            ROOT_LF_BATCH,
299	        );
300	    }
301	}
302	
303	// --- Library: same byte rule through roottrace::verify_membership ----------
304	
305	#[test]
306	fn library_verifies_lf_containing_records_with_typed_result() {
307	    let cases: &[(&[u8], String, u64, u64, &str)] = &[
308	        (REC_LF_RICH, proof_json(1, 0, ROOT_LF_RICH_SINGLE, &[]), 1, 0, ROOT_LF_RICH_SINGLE),
309	        (REC_LF_RICH, proof_json(9, 4, ROOT_LF_BATCH, PATH_LF_BATCH_M4), 9, 4, ROOT_LF_BATCH),
310	        (REC_ONE_LF, proof_json(1, 0, ROOT_ONE_LF_SINGLE, &[]), 1, 0, ROOT_ONE_LF_SINGLE),
311	        (REC_ONE_LF, proof_json(9, 8, ROOT_LF_BATCH, PATH_LF_BATCH_M8), 9, 8, ROOT_LF_BATCH),
312	    ];
313	    for (record, proof, size, index, root) in cases {
314	        let trusted_root = hash_of(root);
315	        let m = verify_membership(record, proof.as_bytes(), *size, &trusted_root)
316	            .unwrap_or_else(|e| panic!("index {index} of tree {size} must verify: {e}"));
317	        assert_eq!(m.leaf_index(), *index);
318	        assert_eq!(m.tree_size(), *size);
319	        assert_eq!(m.root(), &trusted_root);
320	    }
321	}
322	
323	#[test]
324	fn library_lf_record_mutations_are_verification_failed() {
325	    let single = proof_json(1, 0, ROOT_LF_RICH_SINGLE, &[]);
326	    let batch = proof_json(9, 4, ROOT_LF_BATCH, PATH_LF_BATCH_M4);
327	    let single_root = hash_of(ROOT_LF_RICH_SINGLE);
328	    let batch_root = hash_of(ROOT_LF_BATCH);
329	
330	    let no_trailing = &REC_LF_RICH[..REC_LF_RICH.len() - 1];
331	    let mut internal_changed = REC_LF_RICH.to_vec();
332	    internal_changed[21] = 0x0b;
333	
334	    let one_lf_single = proof_json(1, 0, ROOT_ONE_LF_SINGLE, &[]);
335	    let one_lf_root = hash_of(ROOT_ONE_LF_SINGLE);
336	
337	    let failures: &[(&[u8], &[u8], u64, &[u8; 32])] = &[
338	        (no_trailing, single.as_bytes(), 1, &single_root),
339	        (no_trailing, batch.as_bytes(), 9, &batch_root),
340	        (&internal_changed, single.as_bytes(), 1, &single_root),
341	        (&internal_changed, batch.as_bytes(), 9, &batch_root),
342	        // The one-LF record is not the empty record, and vice versa.
343	        (b"", one_lf_single.as_bytes(), 1, &one_lf_root),
344	        (b"\n\n", one_lf_single.as_bytes(), 1, &one_lf_root),
345	    ];
346	    for (record, proof, size, root) in failures {
347	        match verify_membership(record, proof, *size, root) {
348	            Err(VerifyError::VerificationFailed(_)) => {}
349	            other => panic!(
350	                "record {record:?} against tree {size} must be VerificationFailed, got {other:?}"
351	            ),
352	        }
353	    }
354	}
